  const cache = {}; const col = e => { const k = modo === 'instalacion' ? (VIGAS_CRUZADAS.has(e.id) ? 'x' : 'g') : modo === 'tipo' ? e.t : modo === 'nivel' ? e.l : est(e.id); return cache[k] ??= colorDe(e); };
