  m.userData.id = 'san:' + tr.id; escena.add(m); sanMallas.push(m);
  SANP[m.userData.id] = { k: 'tramo', o: tr, m, nivel: PISO_NIVEL[tr.piso], centro: pts[Math.floor(pts.length / 2)].clone().lerp(pts[Math.ceil((pts.length - 1) / 2)], 0.5) };
